# =====================================================
#  Preloader "Delarosa studio" v2
#  1) La rosa y el texto se dibujan solos
#  2) La mariposa entra volando y se posa en la "o" de "studio"
#  3) Todo se desdibuja y la mariposa se va -> loop
#  Blender 3.6 / 4.x / 5.x
#  Uso: pestaña Scripting > New > pegar > Run Script (Alt+P)
# =====================================================
import bpy, math

# ---------- AJUSTES ----------
FPS          = 30
DIBUJO_SEG   = 4.0   # rosa + texto dibujandose
