POSAR_EN     = (1093, 922)
TAM_POSADA   = 0.5    # tamano de la mariposa posada (1 = tamano del logo)
ENTRA_DESDE  = (1480, 330)   # punto de entrada (fuera del cuadro, a la derecha)
SALE_HACIA   = (1420, -160)  # hacia donde se va al final
# -----------------------------

